mapper.select:
SELECT s.SUMMARY_ID, s.MODEL_ID, s.PERIOD, s.VERSION, s.SUMMARY_TYPE, s.DIMENSION_CODE, s.DIMENSION_NAME, s.SUMMARY_VALUE, s.SUMMARY_METHOD, s.DATA_COUNT, s.STATUS, s.ERROR_MESSAGE, s.CREATE_USER, s.CREATE_TIME, m.MODEL_NAME FROM TBL_BUDGET_SUMMARY s LEFT JOIN TBL_BUDGET_MODEL m ON s.MODEL_ID = m.MODEL_ID WHERE s.ORG_ID = #{param.orgId}
AND s.MODEL_ID = #{param.modelId}
AND s.PERIOD = #{param.period}
AND s.VERSION = #{param.version}
AND s.SUMMARY_TYPE = #{param.summaryType}
AND s.DIMENSION_CODE LIKE CONCAT('%', #{param.dimensionCode}, '%')
AND s.STATUS = #{param.status}
AND s.CREATE_TIME >= #{param.startTime}
AND s.CREATE_TIME <= #{param.endTime}
ORDER BY s.CREATE_TIME DESC
